/** Struck from outside. Onset reads the nation's authored `geo.disasterExposure`. */
export declare const ACUTE_CONDITIONS: readonly ["earthquake", "flood", "drought", "cyclone", "wildfire", "pandemic", "tornado", "winter-storm", "heat-wave"];
